import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import API from '../services/api';

export default function Dashboard() {
  const { user } = useAuth();
  const [stats, setStats] = useState({ docs: 0, categories: 0, users: 0 });

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [docsRes, catRes] = await Promise.all([
          API.get('/documents?limit=1'),
          API.get('/categories')
        ]);
        const s = { docs: docsRes.data.total || 0, categories: catRes.data.length || 0, users: 0 };
        if (user.role === 'Admin') {
          const usersRes = await API.get('/auth/users');
          s.users = usersRes.data.length;
        }
        setStats(s);
      } catch {}
    };
    fetchStats();
  }, [user.role]);

  const cards = [
    { label: 'Total Documents', value: stats.docs, color: '#1a237e' },
    { label: 'Categories', value: stats.categories, color: '#00695c' },
    ...(user.role === 'Admin' ? [{ label: 'Total Users', value: stats.users, color: '#e65100' }] : [])
  ];

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Welcome, {user.name}</h2>
      <p style={styles.role}>Role: <strong>{user.role}</strong></p>
      <div style={styles.grid}>
        {cards.map(c => (
          <div key={c.label} style={{ ...styles.card, borderTop: `4px solid ${c.color}` }}>
            <p style={styles.cardLabel}>{c.label}</p>
            <p style={{ ...styles.cardValue, color: c.color }}>{c.value}</p>
          </div>
        ))}
      </div>
      <div style={styles.infoBox}>
        <h3>Role Permissions</h3>
        <ul style={styles.list}>
          {user.role === 'Admin' && <><li>✅ Full system access</li><li>✅ View audit logs</li><li>✅ Manage users & categories</li></>}
          {user.role === 'Record Manager' && <><li>✅ Upload & manage documents</li><li>✅ Create categories</li><li>✅ Version control</li></>}
          {user.role === 'Authorized User' && <><li>✅ View & download documents</li><li>✅ Search & filter</li></>}
          {user.role === 'Auditor' && <><li>✅ View audit logs</li><li>✅ Generate reports</li><li>✅ View all documents</li></>}
        </ul>
      </div>
    </div>
  );
}

const styles = {
  container: { padding: '24px', maxWidth: '1000px', margin: '0 auto' },
  heading: { color: '#1a237e', marginBottom: '4px' },
  role: { color: '#555', marginBottom: '24px' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '16px', marginBottom: '24px' },
  card: { background: '#fff', padding: '20px', borderRadius: '8px', boxShadow: '0 1px 6px rgba(0,0,0,0.1)' },
  cardLabel: { color: '#666', fontSize: '13px', marginBottom: '8px' },
  cardValue: { fontSize: '32px', fontWeight: 'bold', margin: 0 },
  infoBox: { background: '#fff', padding: '20px', borderRadius: '8px', boxShadow: '0 1px 6px rgba(0,0,0,0.1)' },
  list: { paddingLeft: '20px', lineHeight: '2' }
};
